package main

import (
	"fmt"
	"sort"
)

func topoOrder(n int, adj [][]int, indeg []int) []int {
	var ready []int
	for u := 0; u < n; u++ {
		if indeg[u] == 0 {
			ready = append(ready, u)
		}
	}
	var order []int
	for len(ready) > 0 {
		sort.Ints(ready) // smallest-numbered ready course first
		u := ready[0]
		ready = ready[1:]
		order = append(order, u)
		for _, v := range adj[u] {
			indeg[v]-- // remove the edge u -> v
			if indeg[v] == 0 {
				ready = append(ready, v)
			}
		}
	}
	return order
}

func main() {
	var n, m int
	fmt.Scan(&n, &m)
	adj := make([][]int, n)
	indeg := make([]int, n)
	for i := 0; i < m; i++ {
		var u, v int
		fmt.Scan(&u, &v)
		adj[u] = append(adj[u], v)
		indeg[v]++
	}
	order := topoOrder(n, adj, indeg)
	if len(order) < n {
		fmt.Println("cycle")
		return
	}
	fmt.Println("order:", order)
}

