package main

import (
	"container/heap"
	"fmt"
	"math"
)

type Edge struct{ To, W int }

type Item struct{ Dist, Node int }

type MinHeap []Item

func (h MinHeap) Len() int           { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i].Dist < h[j].Dist }
func (h MinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MinHeap) Push(x interface{}) {
	*h = append(*h, x.(Item))
}

func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func shortest(adj [][]Edge, s, t int) int {
	dist := make([]int, len(adj))
	for i := range dist {
		dist[i] = math.MaxInt64 // infinity: not reached yet
	}
	dist[s] = 0
	h := &MinHeap{{Dist: 0, Node: s}}
	for h.Len() > 0 {
		it := heap.Pop(h).(Item)
		if it.Dist > dist[it.Node] {
			continue // stale entry: a shorter path was already found
		}
		for _, e := range adj[it.Node] {
			if nd := it.Dist + e.W; nd < dist[e.To] {
				dist[e.To] = nd
				heap.Push(h, Item{Dist: nd, Node: e.To})
			}
		}
	}
	return dist[t]
}

func main() {
	var n, m int
	fmt.Scan(&n, &m)
	adj := make([][]Edge, n)
	for i := 0; i < m; i++ {
		var u, v, w int
		fmt.Scan(&u, &v, &w)
		adj[u] = append(adj[u], Edge{To: v, W: w})
		adj[v] = append(adj[v], Edge{To: u, W: w})
	}
	var s, t int
	fmt.Scan(&s, &t)
	if d := shortest(adj, s, t); d == math.MaxInt64 {
		fmt.Printf("%d -> %d: INF\n", s, t)
	} else {
		fmt.Printf("%d -> %d: %d\n", s, t, d)
	}
}
